with feeders as (select * from (
    select
        md5(upper(HUB_CLAIM_BK__K0)) as HUB_CLAIM_HK,
        coalesce(nullif(trim(TYPE),''),'') || '@' || coalesce(nullif(trim(IMPACTED_COVER_CODE),''),'') as RESERVE_HEAD,
        TYPE as RESERVE_TYPE,
        RESERVE_AMOUNT as CURRENT_RESERVE_AMOUNT,
