        null::varchar as RESERVE_STATUS,
        'MAXI_HLTH_CLM_VW_DATA_CLAIM_DETAIL_CLAIM_RESERVE_ATTRIBUTES_PIVOT_VW' as RECORD_SOURCE,
        current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_clm_cd_clm_reserve_attr_pv') }}
    where HUB_CLAIM_K0__EMIT
    union all
    select
        md5(upper(HUB_CLAIM_BK__K0)) as HUB_CLAIM_HK,
        coalesce(nullif(trim(TYPE),''),'') || '@' || coalesce(nullif(trim(IMPACTED_COVER_CODE),''),'') as RESERVE_HEAD,
        TYPE as RESERVE_TYPE,
        RESERVE_AMOUNT as CURRENT_RESERVE_AMOUNT,
        RESERVE_DATE as RESERVE_REVISION_DATE,
        REASON as RESERVE_REVISION_REASON,
        null::varchar as PAID_TO_DATE_AMOUNT,
        null::varchar as OUTSTANDING_RESERVE_AMOUNT,
        USER_CODE as RESERVE_SET_BY_REFERENCE,
        STATUS as RESERVE_STATUS,
        'MAXI_HLTH_CLM_VW_DATA_CLAIM_DETAIL_CLAIM_RESERVE_HISTORY_ATTRIBUTES_PIVOT_VW' as RECORD_SOURCE,
        current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_clm_cd_clm_reserve_history_attr_pv') }}
    where HUB_CLAIM_K0__EMIT
)), hashed as (select *,
        case when RESERVE_TYPE is not null or CURRENT_RESERVE_AMOUNT is not null or RESERVE_REVISION_DATE is not null or RESERVE_REVISION_REASON is not null or PAID_TO_DATE_AMOUNT is not null or OUTSTANDING_RESERVE_AMOUNT is not null or RESERVE_SET_BY_REFERENCE is not null or RESERVE_STATUS is not null
             then md5(upper(coalesce(RESERVE_TYPE::varchar,'') || '||' || coalesce(CURRENT_RESERVE_AMOUNT::varchar,'') || '||' || coalesce(RESERVE_REVISION_DATE::varchar,'') || '||' || coalesce(RESERVE_REVISION_REASON::varchar,'') || '||' || coalesce(PAID_TO_DATE_AMOUNT::varchar,'') || '||' || coalesce(OUTSTANDING_RESERVE_AMOUNT::varchar,'') || '||' || coalesce(RESERVE_SET_BY_REFERENCE::varchar,'') || '||' || coalesce(RESERVE_STATUS::varchar,'')))
        end as SAT_CLAIM_RESERVE_HASHDIFF
    from feeders)

